import 'dart:convert';import 'package:get/get.dart';import 'package:flutter/cupertino.dart';import 'package:flutter/material.dart';import 'package:flutter/material.dart' as widgetRow;import 'package:speedotrack/activity/activity_about_us.dart';import 'package:speedotrack/activity/activity_image_zoom.dart';import 'package:speedotrack/network/network_api_request.dart';import 'package:url_launcher/url_launcher.dart';import '../globals.dart';class ImageModel {  final String imageLink;  final String imageName;  final String dateTime;  final String lat;  final String lng;  ImageModel(this.imageLink, this.imageName, this.dateTime, this.lat, this.lng);}class ImageActivity extends StatefulWidget {  @override  _ImageActivityState createState() => _ImageActivityState();}class _ImageActivityState extends State<ImageActivity> {  List<ImageModel> imageModelList = [];  final GlobalKey<ScaffoldMessengerState> _scaffoldKey =      new GlobalKey<ScaffoldMessengerState>();  bool loading = false;  void fetchData() async {    try {      // Traccar REST API position/media endpoint      var responseDocument = await NetworkHelper().requestDataFromNetworkWithTimeoutGET(        urlFile: '/api/positions',        body: {},        context: context,      );      if (responseDocument != null && responseDocument.isNotEmpty) {        List<dynamic> positions = json.decode(responseDocument);        for (var pos in positions) {          // Check if position contains an image attribute or media file          Map<String, dynamic> attributes = pos['attributes'] ?? {};          String? imageName = attributes['image'] ?? attributes['file'];          if (imageName != null && imageName.isNotEmpty) {            String imageLink = '${Globals.baseUrl}/api/media/$imageName';            String dateTime = pos['fixTime'] ?? pos['serverTime'] ?? '';            String lat = pos['latitude']?.toString() ?? '0.0';            String lng = pos['longitude']?.toString() ?? '0.0';            String name = attributes['description'] ?? imageName;            imageModelList.add(ImageModel(imageLink, name, dateTime, lat, lng));          }        }      }    } catch (e) {      debugPrint('Error fetching Traccar image positions: $e');    } finally {      setState(() {        loading = true;      });    }  }  @override  void initState() {    super.initState();    fetchData();  }  @override  Widget build(BuildContext context) {    double _crossAxisSpacing = 0, _mainAxisSpacing = 0, _aspectRatio = 0.7;    int _crossAxisCount = 2;    return Scaffold(      key: _scaffoldKey,      backgroundColor: Color(0xFFF6F6F6),      appBar: AppBar(        backgroundColor: Globals.appColor,        elevation: 0.0,        title: Text(          'imageGallery'.tr,          style: TextStyle(color: Color(0xFFF6F6F6), fontFamily: 'Baloo_Thambi_2'),        ),        iconTheme: IconThemeData(          color: Color(0xFFF6F6F6),        ),      ),      body: Container(        height: double.infinity,        width: double.infinity,        child: loading            ? GridView.builder(                itemCount: imageModelList.length,                gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(                  crossAxisCount: _crossAxisCount,                  crossAxisSpacing: _crossAxisSpacing,                  mainAxisSpacing: _mainAxisSpacing,                  childAspectRatio: _aspectRatio,                ),                itemBuilder: (BuildContext context, int index) {                  return Padding(                    padding: const EdgeInsets.all(5.0),                    child: Card(                      elevation: 2,                      shape: RoundedRectangleBorder(                          borderRadius: BorderRadius.all(Radius.circular(5))),                      child: Column(                        mainAxisSize: MainAxisSize.max,                        children: <Widget>[                          Padding(                            padding: const EdgeInsets.all(10),                            child: AspectRatio(                                aspectRatio: 1,                                child: InkWell(                                    onTap: () {                                      Navigator.push(                                          context,                                          CupertinoPageRoute(                                              builder: (context) => ImageZoomActivity(                                                  url: imageModelList[index].imageLink)));                                    },                                    child: Image.network(                                      imageModelList[index].imageLink,                                      errorBuilder: (context, error, stackTrace) =>                                          Icon(Icons.broken_image, size: 50, color: Colors.grey),                                    ))),                          ),                          Padding(                            padding: const EdgeInsets.all(10),                            child: widgetRow.Row(                              mainAxisSize: MainAxisSize.max,                              mainAxisAlignment: MainAxisAlignment.spaceBetween,                              children: <Widget>[                                Expanded(                                    child: Column(                                  crossAxisAlignment: CrossAxisAlignment.start,                                  mainAxisSize: MainAxisSize.max,                                  children: <Widget>[                                    Text(imageModelList[index].imageName,                                        maxLines: 1,                                        style: TextStyle(                                            fontSize: 16,                                            fontWeight: FontWeight.bold,                                            color: Globals.appColor,                                            fontFamily: 'Montserrat')),                                    SizedBox(                                      height: 5,                                    ),                                    Text(imageModelList[index].dateTime,                                        maxLines: 1,                                        style: TextStyle(                                            fontSize: 12,                                            color: Colors.grey,                                            fontFamily: 'Baloo_Thambi_2')),                                    SizedBox(                                      height: 5,                                    ),                                    InkWell(                                      onTap: () {                                        fetchAddress(imageModelList[index].lat,                                            imageModelList[index].lng);                                      },                                      child: Text('showAddress'.tr,                                          maxLines: 1,                                          style: TextStyle(                                              fontSize: 12,                                              color: Colors.blueAccent,                                              fontFamily: 'Baloo_Thambi_2')),                                    ),                                  ],                                )),                                Expanded(                                  child: InkWell(                                    onTap: () {                                      openMap(imageModelList[index].lat,                                          imageModelList[index].lng);                                    },                                    child: Container(                                      padding: EdgeInsets.all(5),                                      child: Image.asset('images/imageMap.png'),                                      height: 35,                                      width: 35,                                    ),                                  ),                                ),                              ],                            ),                          ),                        ],                      ),                    ),                  );                },              )            : Center(                child: CircularProgressIndicator(                    backgroundColor: Color(0xFFF6F6F6),                    valueColor: new AlwaysStoppedAnimation<Color>(                      Globals.appColor,                    )),              ),      ),    );  }  static Future<void> openMap(String latitude, String longitude) async {    String googleUrl =        'https://www.google.com/maps/search/?api=1&query=$latitude,$longitude';    if (await canLaunch(googleUrl)) {      await launch(googleUrl);    } else {      throw 'Could not open the map.';    }  }  fetchAddress(String lat, String lng) async {    // Traccar Geocode API connection    var response = await NetworkHelper().requestDataFromNetwork(        urlFile: '/api/server/geocode',        body: {'latitude': lat, 'longitude': lng},        context: context);    if (response != null && response.isNotEmpty) {      _scaffoldKey.currentState!.showSnackBar(new SnackBar(        content: new Text('$response'),        duration: Duration(seconds: 5),      ));    } else {      _scaffoldKey.currentState!.showSnackBar(new SnackBar(        content: new Text('noDataItem'.tr),        duration: Duration(seconds: 2),      ));    }  }}